mapper.select:
SELECT id, order_no, user_id, total_amount, status, address_name, address_phone, address_detail, create_time, shipped_time, refunded_time, express_company, express_no, express_courier, express_status, received_time, confirmed_time, sender_name, sender_address, sender_phone
FROM `order`
WHERE id = #{id}

SELECT id, order_no, user_id, total_amount, status, address_name, address_phone, address_detail, create_time, shipped_time, refunded_time, express_company, express_no, express_courier, express_status, received_time, confirmed_time, sender_name, sender_address, sender_phone
FROM `order`
WHERE order_no = #{orderNo}

SELECT id, order_id, product_id, product_name, product_image, selected_spec, price, quantity, create_time
FROM order_item
WHERE order_id = #{orderId}

mapper.update:
UPDATE `order` SET status = 'completed', received_time = NOW(),
       confirmed_time = NOW(), express_status = 'signed'
WHERE id = #{id}

UPDATE `order` SET express_status = #{expressStatus},
       received_time = CASE WHEN #{expressStatus} = 'signed' THEN NOW() ELSE received_time END
WHERE id = #{id}
